import React from 'react';
import { Link } from 'react-router-dom';
import styled from 'styled-components';
import hummingbirdImage from '../assets/images/hummingbird.jpg';

const WelcomeContainer = styled.div`
  max-width: 480px;
  margin: 0 auto;
  padding: 20px;
  background-color: white;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
`;

const LogoImage = styled.img`
  width: 180px;
  margin-bottom: 30px;
  transition: transform 0.3s ease;
  
  &:hover {
    transform: scale(1.05);
  }
`;

const Title = styled.h1`
  font-size: 24px;
  margin-bottom: 10px;
  text-align: center;
`;

const Description = styled.p`
  color: #666;
  margin-bottom: 30px;
  text-align: center;
`;

const CreateButton = styled.button`
  background-color: #6c25ff;
  color: white;
  border: none;
  border-radius: 4px;
  padding: 12px;
  font-size: 16px;
  cursor: pointer;
  margin-bottom: 15px;
  width: 100%;
  transition: all 0.3s ease;
  
  &:hover {
    background-color: #5a1ee0;
    transform: translateY(-2px);
    box-shadow: 0 4px 8px rgba(108, 37, 255, 0.3);
  }
`;

const LoginLink = styled(Link)`
  display: block;
  background-color: #e9d5ff;
  color: #333;
  text-decoration: none;
  text-align: center;
  border-radius: 4px;
  padding: 12px;
  font-size: 16px;
  width: 100%;
  transition: all 0.3s ease;
  
  &:hover {
    background-color: #dbc1ff;
    transform: translateY(-2px);
    box-shadow: 0 4px 8px rgba(233, 213, 255, 0.4);
  }
`;

const ButtonContainer = styled.div`
  width: 100%;
  max-width: 300px;
`;

const Welcome = () => {
  return (
    <WelcomeContainer>
      <LogoImage src={hummingbirdImage} alt="PopX Logo" />
      
      <Title>Welcome to PopX</Title>
      <Description>
        Lorem ipsum dolor sit amet, consectetur adipiscing elit.
      </Description>
      
      <ButtonContainer>
        <Link to="/register" style={{ textDecoration: 'none' }}>
          <CreateButton>Create Account</CreateButton>
        </Link>
        
        <LoginLink to="/login">Already Registered? Login</LoginLink>
      </ButtonContainer>
    </WelcomeContainer>
  );
};

export default Welcome;
